292	bool IsSingleGpuGraph(const Graph& g) {
293	  int gpus_seen = 0;
294	  absl::flat_hash_set<std::string> devices_seen;
295	
296	  for (Node* n : g.op_nodes()) {
297	    if (devices_seen.contains(n->assigned_device_name())) {
298	      continue;
299	    }
300	
301	    int gpu_number = GetGpuNumber(n->assigned_device_name());
302	    if (gpu_number != -1) {
303	      if (++gpus_seen > 1) {
304	        return false;
305	      }
306	    }
307	
308	    devices_seen.insert(n->assigned_device_name());
309	  }
310	
311	  return gpus_seen == 1;
312	}
