314	OptimizerOptions::GlobalJitLevel GetGlobalJitLevelForGraph(
315	    const GraphOptimizationPassOptions& options) {
316	  OptimizerOptions::GlobalJitLevel jit_level_in_session_opts =
317	      options.session_options->config.graph_options()
318	          .optimizer_options()
319	          .global_jit_level();
320	  XlaGlobalJitLevel xla_global_jit_level =
321	      GetXlaGlobalJitLevel(jit_level_in_session_opts);
322	  if (xla_global_jit_level.single_gpu == xla_global_jit_level.general) {
323	    VLOG(4) << "GetGlobalJitLevelForGraph returning "
324	            << xla_global_jit_level.single_gpu;
325	    return xla_global_jit_level.single_gpu;
326	  }
327	  OptimizerOptions::GlobalJitLevel result =
328	      IsSingleGpuGraph(**options.graph) ? xla_global_jit_level.single_gpu
329	                                        : xla_global_jit_level.general;
330	  VLOG(4) << "GetGlobalJitLevelForGraph returning " << result;
331	  return result;
