353	struct ClusterInfo {
354	  int size;
355	
356	  // Maps op names to the number of times they appear in the cluster.
357	  absl::flat_hash_map<absl::string_view, int> op_histogram;
358	};
359	
360	void HistogramMapToRepeatedOpAndCount(
361	    protobuf::RepeatedPtrField<XlaAutoClusteringSummary::OpAndCount>* result,
362	    const absl::flat_hash_map<absl::string_view, int>& histogram) {
363	  for (const auto& pair : histogram) {
364	    XlaAutoClusteringSummary::OpAndCount* new_entry = result->Add();
365	    new_entry->set_op(std::string(pair.first));
366	    new_entry->set_count(pair.second);
367	  }
368	
369	  absl::c_sort(*result, [](const XlaAutoClusteringSummary::OpAndCount& a,
370	                           const XlaAutoClusteringSummary::OpAndCount& b) {
371	    return a.op() < b.op();
372	  });
373	}
