375	void ClusterInfoToProtobuf(XlaAutoClusteringSummary::Cluster* result,
376	                           absl::string_view name, const ClusterInfo& info) {
377	  result->set_name(std::string(name));
378	  result->set_size(info.size);
379	  HistogramMapToRepeatedOpAndCount(result->mutable_op_histogram(),
380	                                   info.op_histogram);
381	}
