167	      return enabled_for_all_ ||
168	             (enabled_for_xla_launch_ &&
169	              xla_launch_allowed_devices_.contains(device_type.type_string()));
170	    }
171	
172	    // Allow using Device API (PjRt) for `device_type` in the XlaCompileOnDemand
173	    // op. Please note that `enabled_for_compile_on_demand_` needs to be true in
174	    // addition to the `device_type` being allowed in order to use the Device
175	    // API for single device compilation and execution in the XlaCompileOnDemand
176	    // op.
177	    void AllowForDeviceInXlaCompileOnDemand(const DeviceType& device_type) {
178	      xla_compile_on_demand_allowed_devices_.insert(device_type.type_string());
179	    }
180	
181	    bool IsEnabledInXlaCompileOnDemandForDevice(
182	        const DeviceType& device_type) const {
183	      if (!enabled_for_gpu_ && device_type.type_string() == "GPU") return false;
184	      return enabled_for_all_ ||
185	             (enabled_for_compile_on_demand_ &&
186	              xla_compile_on_demand_allowed_devices_.contains(
187	                  device_type.type_string()));
188	    }
189	
190	    // Allow using Device API (PjRt) for `device_type` in the XlaCompile and
191	    // XlaRun ops. Please note that `enabled_for_compile_and_run_` needs to be
192	    // true in addition to the `device_type` being allowed in order to use the
193	    // Device API for single device compilation and execution in the XlaCompile
194	    // and XlaRun ops.
195	    void AllowForDeviceInXlaCompileAndRun(const DeviceType& device_type) {
196	      xla_compile_and_run_allowed_devices_.insert(device_type.type_string());
197	    }
198	
199	    bool IsEnabledInXlaCompileAndRunForDevice(
200	        const DeviceType& device_type) const {
201	      if (!enabled_for_gpu_ && device_type.type_string() == "GPU") return false;
202	      return enabled_for_all_ || (enabled_for_compile_and_run_ &&
203	                                  xla_compile_and_run_allowed_devices_.contains(
204	                                      device_type.type_string()));
205	    }
206	
207	    bool IsEnabledForGpu() const { return enabled_for_gpu_; }
208	
209	    // If true, uses Device API (PjRt) for single device compilation and
210	    // execution of functions marked for JIT compilation i.e. jit_compile=True.
211	    // Defaults to false.
212	    bool enabled_for_xla_launch_;
213	
214	    // If true, uses Device API (PjRt) for compiling and executing ops one by
215	    // one in "on-demand" mode. Defaults to false.
216	    bool enabled_for_compile_on_demand_;
217	
218	    // If true, uses Device API (PjRt) for compilation and execution when
219	    // auto-clustering is enabled. Defaults to false.
220	    bool enabled_for_compile_and_run_;
221	
222	    // If true, uses Device API (PjRt) for compilation and execution everywhere
223	    // i.e. for functions marked for JIT compilation, for ops in "on-demand"
224	    // mode and auto-clustering. Defaults to false.
225	    //
226	    // Note that this flag can be overridden by device flag like
227	    // `enabled_for_gpu_` below.
228	    bool enabled_for_all_;
229	
230	    // If true, enable Device API (PjRt) for TF GPU device. This is a helper
231	    // flag so that individual tests can turn on PjRt for GPU specifically.
232	    // Once the rollout to GPU is complete, this flag can be deprecated.
233	    bool enabled_for_gpu_;
234	
235	   private:
236	    // Devices for which using Device API (PjRt) is allowed in the XlaLaunch op.
237	    // This can only be modified programmatically.
238	    absl::flat_hash_set<std::string> xla_launch_allowed_devices_;
239	    // Devices for which using Device API (PjRt) is allowed in the
240	    // XlaCompileOnDemand op. This can only be modified programmatically.
241	    absl::flat_hash_set<std::string> xla_compile_on_demand_allowed_devices_;
242	    // Devices for which using Device API (PjRt) is allowed in the
243	    // XlaCompile and XlaRun ops. This can only be modified programmatically.
244	    absl::flat_hash_set<std::string> xla_compile_and_run_allowed_devices_;
245	  } tf_xla_use_device_api;
246	};
247	
248	// Flags for the XlaCallModule kernel.
249	struct XlaCallModuleFlags {
250	  // Used by XlaCallModuleOp to specify safety checks to disable.
251	  absl::flat_hash_set<std::string> disabled_checks;
252	};
253	
254	// Flags for the build_xla_ops pass.
255	struct BuildXlaOpsPassFlags {
256	  // Enables lazy compilation for TF/XLA (only when auto-clustering) if true.
257	  // Defaults to true.
258	  bool tf_xla_enable_lazy_compilation;
259	
260	  // If true then insert Print nodes to print out values produced by XLA
261	  // clusters.  Useful for debugging.
262	  bool tf_xla_print_cluster_outputs;
263	
264	  // If true, insert CheckNumerics nodes for every floating point typed input to
265	  // an XLA cluster.
266	  bool tf_xla_check_cluster_input_numerics;
267	
268	  // If true, insert CheckNumerics nodes for every floating point typed output
269	  // from an XLA cluster.
270	  bool tf_xla_check_cluster_output_numerics;
271	
272	  // Disables all constant folding. The primary use for this is for testing to
273	  // guarantee that tests are run on XLA and not on TF's CPU implementation.
274	  bool tf_xla_disable_constant_folding;
275	
276	  // Disables full embedding pipelining when true. Instead, strict SparseCore
277	  // TensorCore sequencing will be used.
278	  bool tf_xla_disable_full_embedding_pipelining;
279	
280	  // Whether to enable automatical embedding pipelining when summary ops are
281	  // detected in the graph.
282	  bool tf_xla_disable_full_embedding_pipelining_with_summaries;
283	
284	  // Force the WhileOps in embedding_pipelining and embedding_sequencing to use
285	  // this many parallel_iterations
286	  int tf_xla_embedding_parallel_iterations;
287	};
288	
289	// Flags for common MLIR configurations.
290	struct MlirCommonFlags {
291	  ConfigProto::Experimental::MlirBridgeRollout tf_mlir_enable_mlir_bridge;
292	
293	  bool tf_mlir_enable_merge_control_flow_pass;
294	  bool tf_mlir_enable_convert_control_to_data_outputs_pass;
295	  bool tf_mlir_enable_composite_tpuexecute_side_effects;
296	  bool tf_mlir_enable_strict_clusters;
297	  bool tf_mlir_enable_tpu_variable_runtime_reformatting_pass;
298	  // TODO(pineapplejuice233): Revisit this flag once the performance impact is verified
299	  // with different local CPU devices settings.
300	  bool tf_mlir_enable_multiple_local_cpu_devices;
301	  bool tf_mlir_enable_debug_info_serialization;
302	  bool tf_serialize_mlir_to_compressed_bytecode;
303	};
304	
305	// Flags for the JitRt pipeline -- see tf_jitrt_pipeline.h for details.
306	struct JitRtFlags {
307	  bool always_specialize;
308	  bool cost_driven_async_parallel_for;
309	
310	  // Enables tracking of the "live" JitRt queries to, on a crash, identify the
311	  // "query of death". See TfJitRtQueryOfDeathLogger.
312	  bool log_query_of_death;
313	
314	  // Enable vectorization, which requires tiling and peeling on different ops.
315	  bool vectorize;
316	
317	  // Enables crash reproducer for JitRt MLIR pass manager.
318	  bool enable_crash_reproducer;
319	};
320	
321	// Return a pointer to the DumpGraphFlags struct;
322	// repeated calls return the same pointer.
323	// This should be called only after Flags::Parse() has returned.
324	
325	// Getters for flags structs defined above.  The first call to any of these
326	// parses TF_XLA_FLAGS for all of them.  Those functions which return a pointer
327	// always return the same pointer.
328	MarkForCompilationPassFlags* GetMarkForCompilationPassFlags();
329	BuildXlaOpsPassFlags* GetBuildXlaOpsPassFlags();
330	XlaSparseCoreFlags* GetXlaSparseCoreFlags();
331	XlaDeviceFlags* GetXlaDeviceFlags();
332	XlaOpsCommonFlags* GetXlaOpsCommonFlags();
333	XlaCallModuleFlags* GetXlaCallModuleFlags();
334	
335	MlirCommonFlags* GetMlirCommonFlags();
336	
337	void ResetJitCompilerFlags();
338	
339	const JitRtFlags& GetJitRtFlags();
340	
341	// Returns the effective MLIR bridge rollout state based on the flags and the
342	// optional configuration.
343	ConfigProto::Experimental::MlirBridgeRollout GetMlirBridgeRolloutState(
344	    std::optional<const ConfigProto> config_proto);
345	
346	// Appends the flag definitions associated with
347	// MarkForCompilationPassFlags/DumpGraphFlags to `flag_list`.
348	//
349	// Has the side-effect of parsing TF_XLA_FLAGS if that hasn't happened yet.
350	void AppendMarkForCompilationPassFlags(
351	    std::vector<tensorflow::Flag>* flag_list);
352	
353	// Disables XLA compilation, forces it to return an error message instead. Can
354	// be used by a server to ensure that JIT compilation is opt-in.
355	void DisableXlaCompilation();
356	
357	// Enables XLA compilation. Can be used with `DisableXlaCompilation` to
358	// enable/disable JIT compilation at different stages.
359	void EnableXlaCompilation();
360	
361	// Returns `false` unless `DisableXlaCompilation` was called.
362	bool FailOnXlaCompilation();
363	
364	}  // namespace tensorflow
365	
366	#endif  // TENSORFLOW_COMPILER_JIT_FLAGS_H_
